    cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if rows:
        axis, wall = 0, rows[0]
    elif cols:
        axis, wall = 1, cols[0]
    else:
        return [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            if value != 2: counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (2,background)]
    if not points: return [row[:] for row in grid]
    if axis == 0:
        lo, hi = min(r for r,c in points), max(r for r,c in points)
        size, object_side = hi-lo+1, (1 if lo>wall else -1)
        dim = h
    else:
        lo, hi = min(c for r,c in points), max(c for r,c in points)
        size, object_side = hi-lo+1, (1 if lo>wall else -1)
        dim = w
    line = wall + object_side*(size+1)
    if 0 <= line < dim:
        # If the measured offset runs into the object, stop at its near edge.
        if axis == 0:
            occupied = {r for r,c in points}
        else:
            occupied = {c for r,c in points}
        if line in occupied:
            near = wall + object_side
            while 0 <= near < dim and near in occupied:
                near += object_side
            line = near-object_side
        out = [row[:] for row in grid]
